  it('decodes server-sent streaming deltas in order', async () => {
    const encoder = new TextEncoder();
    const body = new ReadableStream({
      start(controller) {
        controller.enqueue(encoder.encode('data: {"delta":"안녕"}\n\n'));
        controller.enqueue(encoder.encode('data: {"content":"하세요"}\n\ndata: [DONE]\n\n'));
        controller.close();
      },
    });
    vi.spyOn(globalThis, 'fetch').mockResolvedValue(new Response(body, {
      status: 200,
      headers: { 'Content-Type': 'text/event-stream' },
    }));
    const deltas: string[] = [];

    await apiClient.streamChat({ prompt: '인사', onDelta: (value) => deltas.push(value) });

    expect(deltas).toEqual(['안녕', '하세요']);
  });

  it('parses named, multiline SSE events across arbitrary CRLF chunk boundaries', async () => {
    const encoder = new TextEncoder();
    const chunks = [
      'event: metadata\r', '\n', 'id: evt-7\r\n',
      'data: {"items":\r\n', 'data: []}\r\n\r', '\n',
      ': heartbeat\n\n',
      'event: done\ndata: {"status":"SUCCEEDED"}',
