func postgresRelationAt(tokens []policyToken, cursor int, cteBindings []postgresCTEBinding, allowedUnqualified map[string]struct{}) (postgresRelationRef, bool, error) {
	sawOnly := false
	for cursor < len(tokens) && tokens[cursor].kind == policyWord && !tokens[cursor].quoted {
		optional := strings.ToUpper(tokens[cursor].value)
		if optional != "ONLY" && optional != "LATERAL" {
			break
		}
		sawOnly = sawOnly || optional == "ONLY"
		cursor++
	}
	if sawOnly && cursor < len(tokens) && tokens[cursor].kind == policyLeftParen {
		cursor++
	}
	if cursor >= len(tokens) || tokens[cursor].kind == policyLeftParen {
		return postgresRelationRef{}, false, nil
	}
	if tokens[cursor].kind != policyWord {
		return postgresRelationRef{}, false, ErrUnqualifiedRelation
	}
	if cursor+1 < len(tokens) && tokens[cursor+1].kind == policyLeftParen {
		// A table-valued function is governed by sqlsafe's PostgreSQL intrinsic
		// allowlist and resolves only in pg_catalog at execution time.
		return postgresRelationRef{}, false, nil
	}
	if cursor+2 < len(tokens) && tokens[cursor+1].kind == policyDot && tokens[cursor+2].kind == policyWord {
		if cursor+3 < len(tokens) && tokens[cursor+3].kind == policyDot {
			return postgresRelationRef{}, false, ErrUnqualifiedRelation
		}
		return postgresRelationRef{Schema: postgresIdentifier(tokens[cursor]), Name: postgresIdentifier(tokens[cursor+2]), SchemaQuoted: tokens[cursor].quoted}, true, nil
	}
	name := postgresIdentifier(tokens[cursor])
	if postgresCTEVisible(cteBindings, name, cursor) {
		return postgresRelationRef{}, false, nil
	}
	if _, allowed := allowedUnqualified[name]; allowed && !tokens[cursor].quoted {
		return postgresRelationRef{}, false, nil
	}
	return postgresRelationRef{}, false, ErrUnqualifiedRelation
}

func postgresIdentifier(token policyToken) string {
	if token.quoted {
		return token.value
	}
	return strings.ToLower(token.value)
}

