// validation and execution. Keeping dialect analysis and profile schema checks
// together prevents a caller (including MCP) from reaching an Oracle driver
// through a path that applied only the generic SELECT/WITH keyword check.
func analyzeExecutionPolicy(config Connection, statement string) (sqlsafe.Analysis, error) {
	analysis, err := sqlsafe.RequireReadOnlyDialect(statement, string(config.Dialect))
	if err != nil {
		return analysis, fmt.Errorf("%w: %v", ErrUnsafeStatement, err)
	}
	if err := enforceSchemaPolicy(config, statement); err != nil {
		return analysis, err
	}
	return analysis, nil
}

